// Custom JS Function node: "Extract SRT Sub"
// Position: Input File -> Copy to Working Directory -> Extract SRT Sub -> Begin Command
// Runs after Copy to Working Directory so ffmpeg reads the local cache
// copy (args.inputFileObj._id) instead of the source over the network
// share -- faster on a slow NFS/SMB link. The sidecar still gets written
// next to the real library file: the OUTPUT path is always derived from
// args.originalLibraryFile._id, which stays stable regardless of node
// position, so moving this node after the copy changes only where ffmpeg
// reads from, not where the .srt ends up.
//
// Extracts the first eligible English subtitle stream to a <basename>.eng.srt
// sidecar next to the source file. Pure side effect via its own ffmpeg
// subprocess -- does not touch args.variables.ffmpegCommand, so it has zero
// effect on the main transcode pipeline's pass count.
module.exports = async (args) => {
  const { execFile } = require('child_process');
  const fs = require('fs');

  const readPath = args.inputFileObj._id;
  const libraryPath = args.originalLibraryFile._id;
  const ffmpegPath = args.ffmpegPath || '/usr/bin/ffmpeg';

  const streams = args.inputFileObj?.ffProbeData?.streams || [];
  const engSubs = streams.filter((s) =>
    s.codec_type === 'subtitle'
    && s.tags?.language === 'eng'
    && !['hdmv_pgs_subtitle', 'dvd_subtitle', 'dvb_subtitle', 'dvb_teletext', 'xsub'].includes(s.codec_name)
    && !/commentary|description/i.test(s.tags?.title || ''));

  if (engSubs.length === 0) {
    args.jobLog('No eligible English subtitle track found.');
    return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
  }

  const chosen = engSubs.find((s) => !s.disposition?.hearing_impaired && !s.disposition?.forced) || engSubs[0];
  const outPath = libraryPath.replace(/\.[^/.]+$/, '') + '.eng.srt';

  if (fs.existsSync(outPath)) {
    args.jobLog('eng.srt already exists, skipping: ' + outPath);
    return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
  }

  await new Promise((resolve) => {
    execFile(ffmpegPath, ['-y', '-i', readPath, '-map', `0:${chosen.index}`, outPath],
      { maxBuffer: 1024 * 1024 * 20, timeout: 600000 }, (err, stdout, stderr) => {
        if (err) {
          args.jobLog('Subtitle extraction failed: ' + stderr);
          try { fs.unlinkSync(outPath); } catch (e) { /* nothing to clean up */ }
        } else {
          args.jobLog('Extracted ' + outPath);
        }
        resolve();
      });
  });

  return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
};

// Custom JS Function node: "Select Streams"
// Position: Begin Command -> Select Streams -> Plan Encoders
// Consolidates: Remove Subtitles, Remove Data Streams, Keep Largest Video
// Track, Clean Audio Streams (lang), Remove Commentary Tracks, Tag First
// Audio Track (dedupe + fallback), Reorder Streams.
//
// One pass, flags only. Never writes a file; never clears a `removed` flag
// except in the single, explicitly-logged zero-audio fallback. Must run
// after the flow's ONE Begin Command and before Execute.
//
// Replaces the stock ffmpegCommandRemoveStreamByProperty nodes, whose
// configured `tags:language` / `tags:title` (colon syntax) silently matches
// nothing in current Tdarr (the plugin only supports dot syntax, verified
// against plugin source and thousands of job reports with zero matching
// per-stream log lines). Property access here is native JS, so that
// failure mode no longer exists.
module.exports = async (args) => {
  const streams = args.variables.ffmpegCommand.streams;
  const px = (s) => (s.width && s.height ? s.width * s.height : 0);
  const why = new Map(); // stream -> removal reason, for the decision table
  const mark = (s, reason) => {
    if (!s.removed) { s.removed = true; why.set(s, reason); } // add-only: never resurrects
  };
  const BAD_TITLE = /commentary|description|sdh/i;

  // --- 1. Subtitles (already sidecar'd by Extract SRT Sub) and data streams.
  for (const s of streams) {
    if (s.codec_type === 'subtitle') mark(s, 'subtitle');
    else if (s.codec_type === 'data') mark(s, 'data stream');
  }

  // --- 2. Keep largest video-like stream (embedded cover-art defense).
  // Begin Command relabels disposition.attached_pic streams as
  // codec_type 'attachment', but ffmpeg still encodes them as video at
  // Execute time (NVENC "Frame dimensions" crash, or "Invalid argument" on
  // encoder open for zero-dimension attachments). A real 'video' stream
  // always wins over an 'attachment' one, regardless of pixel count --
  // embedded poster art (e.g. a 2000x3000 mjpeg) can easily out-pixel a
  // real 1920x1080 movie, so pixel count alone is not a safe comparison
  // across the two types. When a real video stream exists, every
  // attachment is removed even if its width/height didn't probe (job
  // ZTgdvBR6V: 14 mjpeg attachments with no probed dimensions all survived
  // filtering and were force-encoded via the global -c:v, killing the
  // whole ffmpeg process). Pixel count only breaks ties within the same
  // type: multiple real video tracks, or (when no real video exists at
  // all) multiple measured attachments. Font attachments carry no
  // width/height and are never touched.
  const realVideo = streams.filter((s) => s.codec_type === 'video' && px(s) > 0);
  const attachments = streams.filter((s) => s.codec_type === 'attachment');
  const measuredAttachments = attachments.filter((s) => px(s) > 0);
  const measured = realVideo.length > 0 ? realVideo : measuredAttachments;
  if (realVideo.length > 0) {
    for (const s of attachments) {
      const dims = s.width ? `${s.width}x${s.height}` : 'unmeasured';
      mark(s, `cover art ${dims} (real video stream present)`);
    }
  }
  if (measured.length > 1) {
    let largest = measured[0];
    for (const s of measured.slice(1)) {
      if (px(s) > px(largest)) largest = s;
    }
    for (const s of measured) {
      if (s !== largest) mark(s, `video ${s.width}x${s.height} < kept ${largest.width}x${largest.height}`);
    }
  }
  // A video-typed stream (not attachment-typed) with missing width/height
  // (broken probe) is deliberately neither compared nor removed -- it can
  // only ever cause an extra copied stream, never the loss of the real
  // movie.

  // --- 3+4. Audio: language filter (keep eng/und; missing tag counts as
  // und) and commentary/description/SDH title filter.
  for (const s of streams) {
    if (s.codec_type !== 'audio') continue;
    const lang = String((s.tags && s.tags.language) || 'und').toLowerCase();
    if (!lang.includes('eng') && !lang.includes('und')) mark(s, `language "${lang}"`);
    const title = (s.tags && s.tags.title) || '';
    if (BAD_TITLE.test(title)) mark(s, `title "${title}"`);
  }

  // --- 5. Dedupe to exactly one audio track, with tiered zero-survivor
  // fallback. This block is the only place in the entire flow allowed to
  // clear a `removed` flag.
  const audio = streams.filter((s) => s.codec_type === 'audio');
  let survivor = audio.find((s) => !s.removed);
  if (!survivor && audio.length > 0) {
    // Nothing survived filtering. Prefer any non-commentary track in any
    // language over a commentary track.
    survivor = audio.find((s) => !BAD_TITLE.test((s.tags && s.tags.title) || '')) || audio[0];
    survivor.removed = false;
    why.delete(survivor);
    args.jobLog(`FALLBACK: no eng/und audio survived filtering; keeping stream #${survivor.index} (${survivor.codec_name}) instead of shipping silent output.`);
  }
  for (const s of audio) {
    if (survivor && s !== survivor) mark(s, 'duplicate audio (one survivor kept)');
  }

  // --- 6. Reorder: video, then audio, then everything else. Execute maps
  // output streams in array order, so a stable sort here is equivalent to
  // the stock Reorder Streams node.
  const rank = (s) => (s.codec_type === 'video' ? 0 : s.codec_type === 'audio' ? 1 : 2);
  streams.sort((a, b) => rank(a) - rank(b)); // Array.sort is stable in Node >= 12

  // --- 7. Decision table: the single job-report artifact that replaces
  // seven nodes' worth of breadcrumbs. Read this before the dispatched
  // ffmpeg command when debugging.
  args.jobLog('--- Select Streams decision table ---');
  for (const s of streams) {
    const dims = s.width ? ` ${s.width}x${s.height}` : '';
    const lang = (s.tags && s.tags.language) || '-';
    const title = (s.tags && s.tags.title) || '';
    const verdict = s.removed ? `REMOVE (${why.get(s) || 'upstream'})` : 'KEEP';
    args.jobLog(`#${s.index} ${s.codec_type}/${s.codec_name}${dims} lang=${lang} title="${title}" -> ${verdict}`);
  }

  return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
};

// Custom JS Function node: "Plan Encoders"
// Position: Select Streams -> Plan Encoders -> Set MKV Container -> Execute
// Consolidates: Check if Video is HEVC, NVENC Turbo Encoder, Check if audio
// is EAC3, Encode AC3 -- and all four branch combinations, with no branches.
//
// Judges the SURVIVING streams (post-filter, post-dedupe, post-fallback),
// fixing two stock-plugin bugs at once: stock checkAudioCodec and stock
// checkVideoCodec both match ANY stream in the raw probe, not the stream
// that actually ships.
//
// Args are pushed as pre-tokenized array elements onto
// overallOuputArguments (Tdarr's own field name), so custom-args fields'
// "no shell quoting" trap is structurally impossible here. Global -c:v/-c:a
// semantics are safe because Select Streams guarantees at most one
// surviving video and one surviving audio stream.
module.exports = async (args) => {
  const cmd = args.variables.ffmpegCommand;
  const out = cmd.overallOuputArguments;
  const inp = cmd.overallInputArguments;
  const survivors = cmd.streams.filter((s) => !s.removed);

  // Alternate CPU (libx265) encoder profiles, not currently wired in.
  // Each is a drop-in replacement for the VIDEO_ARGS declaration below,
  // to trade NVENC speed for CPU-encode efficiency.
  //
  // Movie Baseline:
  //   const VIDEO_ARGS = ['-c:v', 'libx265', '-pix_fmt', 'yuv420p10le', '-preset', 'medium', '-crf', '25',
  //     '-x265-params', 'colorprim=bt709:transfer=bt709:colormatrix=bt709'];
  //
  // Max Savings:
  //   const VIDEO_ARGS = ['-c:v', 'libx265', '-pix_fmt', 'yuv420p10le', '-preset', 'slow', '-crf', '27',
  //     '-x265-params', 'colorprim=bt709:transfer=bt709:colormatrix=bt709'];
  //
  // TV:
  //   const VIDEO_ARGS = ['-c:v', 'libx265', '-pix_fmt', 'yuv420p10le', '-preset', 'medium', '-crf', '25',
  //     '-x265-params', 'colorprim=bt709:transfer=bt709:colormatrix=bt709:aq-mode=2:aq-strength=0.8:psy-rd=1.0'];
  //
  // Validated "Turbo" profile (VMAF-swept). Alternate encoder profiles for
  // experiments live in the README.
  const VIDEO_ARGS = ['-c:v', 'hevc_nvenc', '-pix_fmt', 'p010le', '-preset', 'p4',
    '-rc', 'vbr', '-cq', '31', '-temporal-aq', '1', '-multipass', 'qres', '-bf', '4'];

  // Video: judge the survivor, not the whole probe. codec_type may be
  // 'attachment' if the only video-like stream was an un-competed cover art
  // image -- that is a broken source for a movie library, so fail loudly
  // here instead of letting NVENC crash with "Frame dimensions are less
  // than the minimum supported value".
  const video = survivors.find((s) => s.codec_type === 'video')
    || survivors.find((s) => s.codec_type === 'attachment' && s.width && s.height);
  if (!video) throw new Error('Plan Encoders: no surviving video stream after Select Streams.');
  const isImage = ['mjpeg', 'png', 'bmp', 'gif'].includes(video.codec_name)
    || String(video.codec_long_name || '').includes('image');
  if (video.codec_name === 'hevc') {
    args.jobLog(`video #${video.index} already hevc -> stream copy`);
  } else if (isImage) {
    throw new Error(`Plan Encoders: only video-like survivor #${video.index} is ${video.codec_name} cover art (${video.width}x${video.height}); no real movie stream in source.`);
  } else {
    // Hardware decode the source too, not just encode. -hwaccel cuda
    // auto-picks the matching CUVID decoder (h264_cuvid, hevc_cuvid,
    // av1_cuvid, etc.) for whatever the input actually is, so this one
    // flag covers every codec without per-source branching. Only added
    // when a real re-encode is happening -- a stream-copy job never
    // decodes the video, so hwaccel would be a no-op there anyway.
    //
    // Deliberately NOT adding -hwaccel_output_format cuda. That keeps
    // decoded frames as GPU-resident CUDA surfaces, but VIDEO_ARGS
    // requests -pix_fmt p010le as a plain output option -- converting a
    // CUDA surface to p010le needs an explicit scale_cuda/hwdownload
    // filter, not a bare -pix_fmt, and ffmpeg's auto filter-graph
    // negotiation breaks on that mismatch ("Error reinitializing
    // filters!", confirmed in production on job HxtrklhRCZ). Plain
    // -hwaccel cuda still gets NVDEC hardware decode; frames just come
    // back to system memory afterward, so the existing p010le path is
    // unaffected.
    inp.push('-hwaccel', 'cuda');
    out.push(...VIDEO_ARGS);
    args.jobLog(`video #${video.index} ${video.codec_name} -> hevc_nvenc (Turbo p4/cq31), hw decode via cuda`);
  }

  // Audio: judge the one survivor Select Streams guarantees. Channel count
  // only ever goes down, never up: a 2.0 source stays 2.0, and only a
  // source above 5.1 (7.1 = 8ch) gets downmixed to 5.1. Forcing everything
  // to 5.1/384k used to synthesize channels that were never in the source
  // (job IoZG9j9G0: 192k stereo AC3 -> 384k 5.1 EAC3, +7.9% file size for
  // four channels ffmpeg had to invent).
  const audio = survivors.find((s) => s.codec_type === 'audio');
  if (audio) {
    const srcChannels = audio.channels || 6;
    if (audio.codec_name === 'eac3' && srcChannels <= 6) {
      args.jobLog(`audio #${audio.index} already eac3, ${srcChannels}ch -> stream copy (Atmos-in-EAC3 metadata preserved)`);
    } else if (srcChannels > 6) {
      out.push('-af', 'aformat=channel_layouts=5.1', '-c:a', 'eac3', '-b:a', '384k');
      args.jobLog(`audio #${audio.index} ${audio.codec_name} ${srcChannels}ch -> eac3 5.1 384k (downmixed)`);
    } else {
      const bitrate = srcChannels <= 2 ? '192k' : '384k';
      out.push('-c:a', 'eac3', '-b:a', bitrate);
      args.jobLog(`audio #${audio.index} ${audio.codec_name} ${srcChannels}ch -> eac3 ${srcChannels}ch ${bitrate} (channel count preserved)`);
    }
  } else {
    args.jobLog('no audio stream in source; video-only output.');
  }

  return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
};
